class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def arr_to_list(arr):
    head = None
    tail = None
    for v in arr:
        node = ListNode(v)
        if not head:
            head, tail = node, node
        else:
            tail.next = node
            tail = node
    return head


def list_to_arr(head):
    result = []
    node = head
    while node:
        result.append(node.val)
        node = node.next
    return result


def partition(head_arr, x):
    head = arr_to_list(head_arr)
    before_dummy = ListNode(0)
    after_dummy = ListNode(0)
    before, after = before_dummy, after_dummy

    node = head
    while node:
        if node.val < x:
            before.next = node
            before = before.next
        else:
            after.next = node
            after = after.next
        node = node.next

    after.next = None
    before.next = after_dummy.next

    return list_to_arr(before_dummy.next)

